    10→/// Top-level isolate function for image resize (required for compute)
    11→Uint8List _resizeImageIsolate(Map<String, dynamic> params) {
    12→  final imageBytes = params['imageBytes'] as Uint8List;
    13→  final targetSize = params['targetSize'] as int;
    14→
    15→  var image = img.decodeImage(imageBytes);
    16→  if (image == null) {
    17→    throw Exception('Failed to decode image');
    18→  }
    19→
    20→  // Resize to target size if not already that size
    21→  if (image.width != targetSize || image.height != targetSize) {
    22→    image = img.copyResize(
    23→      image,
    24→      width: targetSize,
    25→      height: targetSize,
    26→      interpolation: img.Interpolation.cubic,
    27→    );
    28→  }
    29→
    30→  // Encode as PNG (lossless intermediate format)
    31→  return Uint8List.fromList(img.encodePng(image));
    32→}
    33→
    34→class ExportService {
    35→  static const int exportSizeSmall = 1080;  // For zoom and front (white bg)
    36→  static const int exportSizeLarge = 2000;  // For alpha (transparent)
    37→  static const int maxFileSizeBytes = 150 * 1024; // 150KB
    38→
    39→  final WebpEncoderService _webpEncoder = WebpEncoderService();
    40→
    41→  /// Prompts user to select export directory (desktop/mobile only).
    42→  /// Returns null if user cancels or on web platform.
    43→  Future<String?> getExportDirectory() async {
    44→    if (kIsWeb) {
    45→      // Web doesn't use directory selection - returns null to signal web mode
    46→      return null;
    47→    }
    48→
    49→    return await FilePicker.platform.getDirectoryPath(
    50→      dialogTitle: 'Select Export Directory',
    51→    );
    52→  }
    53→
    54→  /// Prepare image for export as WebP: resize to target size and compress to stay under 150KB
    55→  Future<Uint8List> _prepareForExport(
    56→    Uint8List imageBytes, {
    57→    required bool preserveTransparency,
    58→    required int targetSize,
    59→  }) async {
    60→    // Run image decoding/resizing in a separate isolate to avoid blocking UI
    61→    final pngBytes = await compute(_resizeImageIsolate, {
    62→      'imageBytes': imageBytes,
    63→      'targetSize': targetSize,
    64→    });
    65→
    66→    // Convert to WebP
    67→    final webpBytes = await _webpEncoder.encodeToWebp(
    68→      pngBytes: pngBytes,
    69→      preserveTransparency: preserveTransparency,
    70→      maxBytes: maxFileSizeBytes,
    71→      targetSize: targetSize,
    72→    );
    73→
    74→    return webpBytes;
    75→  }
    76→
    77→  /// Export images with transparent, zoom, and front background versions
    78→  /// File naming: 3d-filament-{GroupName}-alpha-azurefilm.webp, etc.
    79→  /// Folder structure: {GroupName} {SKU}/
    80→  /// WebP format with lossy (zoom/front) and lossless (transparent) compression
    81→  ///
    82→  /// [directory] - Pre-selected export directory (desktop/mobile).
    83→  ///               Pass null for web platform (uses browser download).
    84→  Future<void> exportDualBackground({
    85→    required List<ExportImageData> images,
    86→    String? directory,
    87→  }) async {
    88→    if (kIsWeb) {
    89→      // Web: Download each file individually (no folder structure)
    90→      for (final imageData in images) {
    91→        final baseName = imageData.groupName.replaceAll(' ', '-');
    92→
    93→        // Export transparent background version (lossless WebP with alpha, 2000x2000)
    94→        final transparentConverted = await _prepareForExport(
    95→          imageData.transparentBytes,
    96→          preserveTransparency: true,
    97→          targetSize: exportSizeLarge,
    98→        );
    99→        await FileSaver.instance.saveFile(
   100→          name: '3d-filament-$baseName-alpha-azurefilm.webp',
   101→          bytes: transparentConverted,
   102→          ext: 'webp',
   103→          mimeType: MimeType.other,
   104→        );
   105→
   106→        // Export zoom version (lossy WebP, 1080x1080)
   107→        final zoomConverted = await _prepareForExport(
   108→          imageData.zoomBytes,
   109→          preserveTransparency: false,
   110→          targetSize: exportSizeSmall,
   111→        );
   112→        await FileSaver.instance.saveFile(
   113→          name: '3d-filament-$baseName-zoom-azurefilm.webp',
   114→          bytes: zoomConverted,
   115→          ext: 'webp',
   116→          mimeType: MimeType.other,
   117→        );
   118→
   119→        // Export front version (lossy WebP, 1080x1080)
   120→        final frontConverted = await _prepareForExport(
   121→          imageData.frontBytes,
   122→          preserveTransparency: false,
   123→          targetSize: exportSizeSmall,
   124→        );
   125→        await FileSaver.instance.saveFile(
   126→          name: '3d-filament-$baseName-front-azurefilm.webp',
   127→          bytes: frontConverted,
   128→          ext: 'webp',
   129→          mimeType: MimeType.other,
   130→        );
   131→      }
   132→    } else if (directory != null) {
   133→      // Desktop/Mobile: Save all files to the pre-selected directory
   134→      for (final imageData in images) {
   135→        // Create folder: "{GroupName} {SKU}"
   136→        final folderName = '${imageData.groupName} ${imageData.sku}'.trim();
   137→        final folderPath = '$directory/$folderName';
   138→        await Directory(folderPath).create(recursive: true);
   139→
   140→        // Generate base filename: replace spaces with "-"
   141→        final baseName = imageData.groupName.replaceAll(' ', '-');
   142→
   143→        // Export transparent background version (lossless WebP with alpha, 2000x2000)
   144→        final transparentConverted = await _prepareForExport(
   145→          imageData.transparentBytes,
   146→          preserveTransparency: true,
   147→          targetSize: exportSizeLarge,
   148→        );
   149→        final transparentFile = File('$folderPath/3d-filament-$baseName-alpha-azurefilm.webp');
   150→        await transparentFile.writeAsBytes(transparentConverted);
   151→
   152→        // Export zoom version (lossy WebP, 1080x1080)
   153→        final zoomConverted = await _prepareForExport(
   154→          imageData.zoomBytes,
   155→          preserveTransparency: false,
   156→          targetSize: exportSizeSmall,
   157→        );
   158→        final zoomFile = File('$folderPath/3d-filament-$baseName-zoom-azurefilm.webp');
   159→        await zoomFile.writeAsBytes(zoomConverted);
   160→
   161→        // Export front version (lossy WebP, 1080x1080)
   162→        final frontConverted = await _prepareForExport(
   163→          imageData.frontBytes,
   164→          preserveTransparency: false,
   165→          targetSize: exportSizeSmall,
   166→        );
   167→        final frontFile = File('$folderPath/3d-filament-$baseName-front-azurefilm.webp');
   168→        await frontFile.writeAsBytes(frontConverted);
   169→      }
   170→    }
   171→  }
   172→}
