    15→class ExportController {
    16→  final Ref _ref;
    17→
    18→  ExportController(this._ref);
    19→
    20→  /// Exports all groups with their selected generations.
    21→  /// [directory] - Pre-selected export directory (desktop/mobile).
    22→  ///               Pass null for web platform (uses browser download).
    23→  Future<void> exportAll({String? directory}) async {
    24→    final groups = _ref.read(groupsProvider);
    25→    final exportService = _ref.read(exportServiceProvider);
    26→    final nanoBananaService = _ref.read(nanoBananaServiceProvider);
    27→    final colorizedNotifier = _ref.read(colorizedImagesProvider.notifier);
    28→    final imageCache = _ref.read(imageCacheServiceProvider);
    29→
    30→    // Prepare export data: for each group, export only the selected generation
    31→    final exportData = <ExportImageData>[];
    32→
    33→    for (final group in groups) {
    34→      // Get the selected generation for this group
    35→      final selectedGeneration = _ref.read(selectedGenerationProvider(group.id));
    36→
    37→      // Get the colorized image for this group's selected generation
    38→      final image = colorizedNotifier.getByGroupAndGeneration(group.id, selectedGeneration);
    39→      if (image == null) continue;
    40→
    41→      // Get base colorized bytes from cache
    42→      final baseColorizedBytes = imageCache.getBaseColorizedImage(image.id);
    43→      if (baseColorizedBytes == null) continue;
    44→
    45→      // Use generation-specific adjustment key
    46→      final adjustmentKey = '${group.id}:$selectedGeneration';
    47→      final adjustments = _ref.read(groupAdjustmentsProvider(adjustmentKey));
    48→
    49→      // Generate transparent background version
    50→      final transparentBytes = await nanoBananaService.applyAdjustments(
    51→        baseColorizedBytes: baseColorizedBytes,
    52→        hue: adjustments.hue,
    53→        saturation: adjustments.saturation,
    54→        brightness: adjustments.brightness,
    55→        contrast: adjustments.contrast,
    56→        sharpness: adjustments.sharpness,
    57→        useWhiteBackground: false,
    58→      );
    59→
    60→      // Generate zoom version (using zoomed SILK template + zoomed carton)
    61→      final zoomBytes = await nanoBananaService.generateZoomImage(
    62→        hexColor: image.appliedHex,
    63→        hue: adjustments.hue,
    64→        saturation: adjustments.saturation,
    65→        brightness: adjustments.brightness,
    66→        contrast: adjustments.contrast,
    67→        sharpness: adjustments.sharpness,
    68→      );
    69→
    70→      // Generate front version (using Kolut in gorila spodaj + CartonGorilla)
    71→      final frontBytes = await nanoBananaService.generateFrontImage(
    72→        hexColor: image.appliedHex,
    73→        hue: adjustments.hue,
    74→        saturation: adjustments.saturation,
    75→        brightness: adjustments.brightness,
    76→        contrast: adjustments.contrast,
    77→        sharpness: adjustments.sharpness,
    78→      );
    79→
    80→      exportData.add(ExportImageData(
    81→        groupName: group.name,
    82→        sku: group.sku,
    83→        transparentBytes: transparentBytes,
    84→        zoomBytes: zoomBytes,
    85→        frontBytes: frontBytes,
    86→      ));
    87→    }
    88→
    89→    await exportService.exportDualBackground(images: exportData, directory: directory);
    90→  }
