    92→  /// Export a single generation from a specific group
    93→  /// [directory] - Pre-selected export directory (desktop/mobile).
    94→  ///               Pass null for web platform (uses browser download).
    95→  Future<void> exportSingleGeneration(String groupId, int generationIndex, {String? directory}) async {
    96→    final colorizedNotifier = _ref.read(colorizedImagesProvider.notifier);
    97→    final colorizedImage = colorizedNotifier.getByGroupAndGeneration(groupId, generationIndex);
    98→
    99→    if (colorizedImage == null) {
   100→      throw Exception('No colorized image found for group $groupId, generation $generationIndex');
   101→    }
   102→
   103→    // Get base colorized bytes from cache
   104→    final imageCache = _ref.read(imageCacheServiceProvider);
   105→    final baseColorizedBytes = imageCache.getBaseColorizedImage(colorizedImage.id);
   106→    if (baseColorizedBytes == null) {
   107→      throw Exception('No base colorized bytes found in cache for image ${colorizedImage.id}');
   108→    }
   109→
   110→    // Get group info for name and SKU
   111→    final groups = _ref.read(groupsProvider);
   112→    final group = groups.firstWhere((g) => g.id == groupId);
   113→
   114→    final exportService = _ref.read(exportServiceProvider);
   115→    final nanoBananaService = _ref.read(nanoBananaServiceProvider);
   116→
   117→    // Use generation-specific adjustment key
   118→    final adjustmentKey = '$groupId:$generationIndex';
   119→    final adjustments = _ref.read(groupAdjustmentsProvider(adjustmentKey));
   120→
   121→    // Generate transparent background version
   122→    final transparentBytes = await nanoBananaService.applyAdjustments(
   123→      baseColorizedBytes: baseColorizedBytes,
   124→      hue: adjustments.hue,
   125→      saturation: adjustments.saturation,
   126→      brightness: adjustments.brightness,
   127→      contrast: adjustments.contrast,
   128→      sharpness: adjustments.sharpness,
   129→      useWhiteBackground: false,
   130→    );
   131→
   132→    // Generate zoom version (using zoomed SILK template + zoomed carton)
   133→    final zoomBytes = await nanoBananaService.generateZoomImage(
   134→      hexColor: colorizedImage.appliedHex,
   135→      hue: adjustments.hue,
   136→      saturation: adjustments.saturation,
   137→      brightness: adjustments.brightness,
   138→      contrast: adjustments.contrast,
   139→      sharpness: adjustments.sharpness,
   140→    );
   141→
   142→    // Generate front version (using Kolut in gorila spodaj + CartonGorilla)
   143→    final frontBytes = await nanoBananaService.generateFrontImage(
   144→      hexColor: colorizedImage.appliedHex,
   145→      hue: adjustments.hue,
   146→      saturation: adjustments.saturation,
   147→      brightness: adjustments.brightness,
   148→      contrast: adjustments.contrast,
   149→      sharpness: adjustments.sharpness,
   150→    );
   151→
   152→    final exportData = ExportImageData(
   153→      groupName: group.name,
   154→      sku: group.sku,
   155→      transparentBytes: transparentBytes,
   156→      zoomBytes: zoomBytes,
   157→      frontBytes: frontBytes,
   158→    );
   159→
   160→    await exportService.exportDualBackground(images: [exportData], directory: directory);
   161→  }
   162→}
