     1→/// Lightweight model for imported images.
     2→/// Binary data (bytes, thumbnailBytes) is stored separately in ImageCacheService
     3→/// to avoid expensive state copies when provider state changes.
     4→class ImportedImage {
     5→  final String id;
     6→  final String filename;
     7→  final DateTime importedAt;
     8→  final bool isSelected;
     9→  final bool isGrouped;
    10→
    11→  const ImportedImage({
    12→    required this.id,
    13→    required this.filename,
    14→    required this.importedAt,
    15→    this.isSelected = false,
    16→    this.isGrouped = false,
    17→  });
    18→
    19→  ImportedImage copyWith({
    20→    String? id,
    21→    String? filename,
